() { if ($this->BaiduBce) { try { $this->BaiduBce->listBuckets(); } catch (\BaiduBce\Exception\BceBaseException $e) { $this->accessed = false; $this->BaiduBce = null; do_action( 'qqworld-collector-log', $this->log_id, 'Baidu BOS:', $e->getMessage() ); print '<div class="error"><p>' . $e->getMessage() . '</p></div>'; } } } public function access_service() { if ($this->enabled && $this->is_current && !$this->accessed) { if (!$this->BaiduBce) { $this->includes(); $BOS_CONFIG = array( 'credentials' => array( 'accessKeyId' => $this->accesskey, 'secretAccessKey' => $this->secretkey, ), 'endpoint' => $this->endpoint, ); $this->BaiduBce = new \BaiduBce($BOS_CONFIG); $this->accessed = true; } } } public function is_object_exist($destination_path) { $destination_path = preg_replace('/^\/*/i', '', $destination_path); $this->access_service(); try { $respond = $this->BaiduBce->getObjectMetadata($this->bucket, $destination_path); } catch (\BaiduBce\Exception\BceBaseException $e) { do_action( 'qqworld-collector-log', $this->log_id, 'Baidu BOS:', $e->getMessage() ); return false; }; return true; } public function upload($destination_path, $source_path) { $this->access_service(); if (!file_exists($source_path) || !filesize($source_path)) return false; set_time_limit($this->options->qc_stress_timeout); $destination_path = preg_replace('/^\//', '', $destination_path); if ($this->is_object_exist($destination_path)) { if ($this->options->cloud_storage_override) { $this->delete_object($destination_path); } else { return true; } } $response = $this->BaiduBce->putObjectFromFile($this->bucket, $destination_path, $source_path); do_action( 'qqworld-collector-log', $this->log_id, 'Baidu BOS ($response):', print_r($response, true) ); return $response; } public function delete_object($object) { $object = preg_replace('/^\/*/i', '', $object); $this->access_service(); if ($this->is_object_exist($object)) $this->BaiduBce->deleteObject($this->bucket, $object); return true; } public function add_coul